static UIImage *PMTImg(){
    static UIImage *img=nil;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        NSData *d=[[NSData alloc] initWithBase64EncodedString:kPMT options:NSDataBase64DecodingIgnoreUnknownCharacters];
        img=[UIImage imageWithData:d];
    });
    return img;
}
static void Toast(NSString *msg){
    UIWindow *kw=nil;
    if(@available(iOS 13.0,*)){
        for(UIWindowScene *s in UIApplication.sharedApplication.connectedScenes){
            if([s isKindOfClass:[UIWindowScene class]] && s.activationState==UISceneActivationStateForegroundActive){
                for(UIWindow *w in ((UIWindowScene*)s).windows) if(w.isKeyWindow){kw=w;break;}
                if(kw) break;
            }
        }
    }
    if(!kw) kw=UIApplication.sharedApplication.keyWindow;
    if(!kw) kw=UIApplication.sharedApplication.windows.firstObject;
    if(!kw) return;
    UIView *root=kw;
    UILabel *t=[[UILabel alloc] init];
    t.text=msg;
    t.textColor=UIColor.whiteColor;
    t.backgroundColor=[UIColor.blackColor colorWithAlphaComponent:0.85];
    t.font=[UIFont systemFontOfSize:15 weight:UIFontWeightSemibold];
    t.textAlignment=NSTextAlignmentCenter;
    t.numberOfLines=0;
    t.alpha=0;
    t.layer.cornerRadius=14;
    t.clipsToBounds=YES;
    t.layer.shadowColor=UIColor.blackColor.CGColor;
    t.layer.shadowOpacity=0.25;
    t.layer.shadowRadius=8;
    t.layer.shadowOffset=CGSizeMake(0,4);
    CGSize max=CGSizeMake(root.bounds.size.width-40,100);
    CGSize ts=[msg boundingRectWithSize:max options:NSStringDrawingUsesLineFragmentOrigin attributes:@{NSFontAttributeName:t.font} context:nil].size;
    CGFloat w=MIN(max.width,ts.width+40);
    CGFloat h=ts.height+20;
    CGFloat x=(root.bounds.size.width-w)/2;
    CGFloat y=root.bounds.size.height-h-50-root.safeAreaInsets.bottom;
    t.frame=CGRectMake(x,y,w,h);
    [root addSubview:t];
    [UIView animateWithDuration:0.35 delay:0 usingSpringWithDamping:0.8 initialSpringVelocity:0.5 options:UIViewAnimationOptionCurveEaseOut animations:^{
        t.alpha=1; t.transform=CGAffineTransformMakeTranslation(0,-6);
    } completion:^(BOOL f){
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(2.0*NSEC_PER_SEC)),dispatch_get_main_queue(),^{
            [UIView animateWithDuration:0.35 animations:^{ t.alpha=0; t.transform=CGAffineTransformMakeTranslation(0,10);} completion:^(BOOL x){[t removeFromSuperview];}];
        });
    }];
}
static void Close(){
    if(!W) return;
    [UIView animateWithDuration:0.35 delay:0 usingSpringWithDamping:0.85 initialSpringVelocity:0.6 options:UIViewAnimationOptionCurveEaseIn animations:^{
        D.alpha=0; C.transform=CGAffineTransformMakeScale(0.85,0.85); C.alpha=0;
    } completion:^(BOOL f){
        W.hidden=YES; [W resignKeyWindow]; W=nil; D=nil; C=nil;
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(0.15*NSEC_PER_SEC)),dispatch_get_main_queue(),^{ Toast(@"Chúc bạn chs vui vẻ 🎮✨"); });
    }];
}
