__attribute__((constructor))
static void TrieuInit(){
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(0.8*NSEC_PER_SEC)),dispatch_get_main_queue(),^{
        if(UIApplication.sharedApplication.keyWindow==nil && UIApplication.sharedApplication.windows.count==0){
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(0.7*NSEC_PER_SEC)),dispatch_get_main_queue(),^{ Show(); });
        }else Show();
    });
}
__attribute__((visibility("default")))
void showTrieuClient(){ Show(); }
